"""Verify original mark-only boundaries and exact already-booked funding keys before reserve."""
from common import *
rd=lambda p:json.loads(p.read_text());w=rd(R/'account_windows.json');P=ROOT/'research/experiments/20261125T074237Z';assert not(R/'reserve_batches').exists()
dc={a:len(w[a]['expected_daily_events_utc']) for a in ['SMA','candidate','l4h02','fewm']};fc={a:w[a]['expected_funding_records'] for a in dc};assert all(v==0 for v in dc.values()) and fc=={'SMA':0,'candidate':0,'l4h02':6,'fewm':6} and all(w[a]['next_daily_decision_utc']=='2026-11-25T00:01:00Z' for a in dc)
for name in ['actual08_nov23_prebinding_source.json','actual16_nov23_prebinding_source.json','actual00_nov24_prebinding_source.json']:
 p=rd(R/name);assert p['passed'] and p['before_any_current_reservation'] and sha(ROOT/p['source'])==p['sha256'] and all(sum(z.values())==6 for z in p['prior_unique_counts'].values()) and all(sum(z.values())==0 for z in p['expected_current_increment_counts'].values())
new=rd(R/'actual08_nov24_prebinding_source.json');assert new['passed'] and new['before_any_current_reservation'] and sha(ROOT/new['source'])==new['sha256'] and {a:sum(z.values()) for a,z in new['prior_unique_counts'].items()}=={'candidate':6,'l4h02':6,'fewm':6} and {a:sum(z.values()) for a,z in new['expected_current_increment_counts'].items()}=={'candidate':0,'l4h02':0,'fewm':0}

last=rd(R/'actual16_nov24_prebinding_source.json');assert last['passed'] and last['before_any_current_reservation'] and sha(ROOT/last['source'])==last['sha256']=='b83d66f870d189d066c4939190c39b16a44e3785ef23277e70d85250a7e8cf5d' and last['first_capture_utc']=='2026-11-25T08:05:57.950668Z' and {a:sum(z.values()) for a,z in last['prior_unique_counts'].items()}=={'candidate':0,'l4h02':0,'fewm':0} and {a:sum(z.values()) for a,z in last['expected_current_increment_counts'].items()}=={'candidate':0,'l4h02':6,'fewm':6}
assert {str(int(z['fundingTime'])*1000000) for xs in last['actual_public_fields'].values() for z in xs}=={'1795536000000000000'}

full=rd(R/'SMA_full76_prebinding.json');assert full['passed'] and full['current_original_daily_event_count']==0 and sha(ROOT/full['authority'])==full['sha256'] and rd(R/'SMA_markonly_kernel_identity.json')['original_Float_financial_arithmetic_unchanged']
for name in ['engine.py','core391_tail_safe.py','market.py','portfolio.py','audit_native.py','observe_l4h02.py','observe_fewm.py','audit_incremental.py']:assert sha(R/name)==sha(P/name)
archiveplan=rd(R/'registry_archive_plan.json');assert archiveplan['planned_before_any_reservation'] is True and archiveplan['own_finished_IDs']==16 and archiveplan['own_raw_reserve_finish_events']==32
put(R/'boundary_unit_verification.json',{'passed':True,'current_daily_event_counts':dc,'actual_funding_counts':fc,'all3perps_old08_16_and_actual00_keys6each_no_repeat':True,'exact_actual00_source_SHA_originalUTC_retained':True,'new16_source_SHA_originalUTC_fields_and_own_unbooked_keys_bound':True,'SMA_full76_guard_exact75prefix_and_markonly_arithmetic':True,'candidate_ETH_existing_signed_units_minus1p754_checked_against_own_audited_state':True,'before_any_current_reservation':True});print('PASS all4 daily0/SMA-C funding0/L4-FEWM funding6each/old source keys6each/new16keys0 before reserve/full76 markonly/8 unchanged kernels')
